    // Skip blank lines
    if trimmed.is_empty() {
      continue
    }
    // Skip comments
    if trimmed.has_prefix("#") {
      continue
    }
    // Table header
    if trimmed.has_prefix("[") {
      if trimmed.ends_with("]") {
        let table_name = trimmed.sub(start=1, end=trimmed.length() - 1).to_owned().trim().to_owned()
        if table_name.is_empty() {
          raise ParseError::EmptyTableName(line_num)
        }
        let parts = split_dotted_key(table_name, line_num) raise
        let full_key = parts.join(".")
        if defined_tables.contains(full_key) {
          raise ParseError::DuplicateKey("table [\{full_key}]", line_num)
        }
        defined_tables.set(full_key, true)
        current_path = parts
      } else {
        raise ParseError::InvalidSyntax("malformed table header", line_num)
      }
      continue
    }
    // Key-value pair
    let eq_pos = find_equals(trimmed, line_num) raise
    let key_part = trimmed.sub(start=0, end=eq_pos).to_owned().trim().to_owned()
    let value_part = trimmed.sub(start=eq_pos + 1).to_owned().trim().to_owned()
    if key_part.is_empty() {
      raise ParseError::InvalidSyntax("empty key", line_num)
    }
    let key_parts = split_dotted_key(key_part, line_num) raise
    let value = parse_value(value_part, line_num) raise
    // Combine current_path (from table) with key_parts
    let full_path : Array[String] = []
    for p in current_path {
      full_path.push(p)
    }
    for p in key_parts {
      full_path.push(p)
    }
    insert_nested(root, full_path, value, line_num) raise
  }
  // Sort keys for deterministic output
  Json::Object(sort_map(root))
}

///|
/// Split a dotted key like "a.b.c" into ["a", "b", "c"].
fn split_dotted_key(key : String, line_num : Int) -> Array[String] raise ParseError {
  let parts = key.split(".").to_array()
  let result : Array[String] = []
  for part in parts {
    let p = part.trim().to_owned()
    if p.is_empty() {
      raise ParseError::InvalidSyntax("empty key segment in dotted key", line_num)
    }
    validate_bare_key(p, line_num) raise
    result.push(p)
  }
  result
}

///|
/// Validate that a bare key contains only valid characters.
fn validate_bare_key(key : String, line_num : Int) -> Unit raise ParseError {
  for i = 0; i < key.length(); i = i + 1 {
    let c = key[i]
    if not(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' || c == '-') {
      raise ParseError::InvalidSyntax("invalid character in key: '\{c}'", line_num)
    }
  }
}

///|
/// Find the position of the first `=` not inside a string.
fn find_equals(line : StringView, line_num : Int) -> Int raise ParseError {
  let mut in_string = false
  let mut i = 0
  while i < line.length() {
    let c = line[i]
    if c == '"' {
      if in_string {
        in_string = false
      } else {
        in_string = true
      }
    } else if c == '=' && not(in_string) {
      return i
    }
    i = i + 1
  }
  raise ParseError::InvalidSyntax("missing '=' in key-value pair", line_num)
}

///|
/// Parse a TOML value: string, integer, boolean, or array.
fn parse_value(text : String, line_num : Int) -> Json raise ParseError {
  let t = text.trim().to_owned()
  if t == "" {
    raise ParseError::InvalidValue("empty value", line_num)
  }
  // String
  if t.has_prefix("\"") {
    return parse_string(t, line_num) raise
  }
  // Boolean
  if t == "true" {
    return Json::True
  }
  if t == "false" {
    return Json::False
  }
  // Array
  if t.has_prefix("[") {
    return parse_array(t, line_num) raise
  }
  // Integer
  if t[0] == '-' || t[0] == '+' || (t[0] >= '0' && t[0] <= '9') {
    return parse_integer(t, line_num) raise
  }
  raise ParseError::InvalidValue("unrecognized value: \{t}", line_num)
}

///|
/// Parse a TOML string value with escape handling.
fn parse_string(text : String, line_num : Int) -> Json raise ParseError {
  let len = text.length()
  if len < 2 || not(text.has_prefix("\"")) || not(text.ends_with("\"")) {
    raise ParseError::UnterminatedString(line_num)
  }
  let inner = text.sub(start=1, end=len - 1)
  let result = StringBuilder::new()
  let mut i = 0
  while i < inner.length() {
    let c = inner[i]
    if c == '\\' {
      if i + 1 >= inner.length() {
        raise ParseError::InvalidEscape("unterminated escape sequence", line_num)
      }
      let next = inner[i + 1]
      match next {
        '"' => {
          result.write_char('"')
          i = i + 2
          continue
        }
        '\\' => {
          result.write_char('\\')
          i = i + 2
          continue
        }
        'n' => {
          result.write_char('\n')
          i = i + 2
          continue
        }
        't' => {
          result.write_char('\t')
          i = i + 2
          continue
        }
        _ => raise ParseError::InvalidEscape("unknown escape sequence: \\\{next}", line_num)
      }
    } else {
      result.write_char(c)
      i = i + 1
    }
  }
  Json::String(result.to_string())
}

///|
/// Parse an integer value.
fn parse_integer(text : String, line_num : Int) -> Json raise ParseError {
  let s = text.trim().to_owned()
  // Validate characters
  let mut start = 0
  if s[0] == '-' || s[0] == '+' {
    start = 1
  }
  if start >= s.length() {
    raise ParseError::InvalidValue("invalid integer: \{s}", line_num)
  }
  for i = start; i < s.length(); i = i + 1 {
    if not(s[i] >= '0' && s[i] <= '9') {
      raise ParseError::InvalidValue("invalid integer: \{s}", line_num)
    }
  }
  let n : Int = @string.from_str(s) catch {
    _ => raise ParseError::InvalidValue("invalid integer: \{s}", line_num)
  }
  Json::Number(n.to_double(), repr=s)
}

///|
/// Parse an array of values.
fn parse_array(text : String, line_num : Int) -> Json raise ParseError {
  let t = text.trim().to_owned()
  if not(t.has_prefix("[") && t.ends_with("]")) {
    raise ParseError::InvalidValue("malformed array", line_num)
  }
  let inner = t.sub(start=1, end=t.length() - 1).to_owned().trim().to_owned()
  if inner.is_empty() {
    return Json::Array([])
  }
  let elements = split_array_elements(inner, line_num) raise
  let result : Array[Json] = []
  for elem in elements {
    result.push(parse_value(elem, line_num) raise)
  }
  Json::Array(result)
}

///|
/// Split array elements respecting nested arrays.
fn split_array_elements(text : String, line_num : Int) -> Array[String] raise ParseError {
  let result : Array[String] = []
  let mut depth = 0
  let mut current = StringBuilder::new()
  let mut i = 0
  while i < text.length() {
    let c = text[i]
    if c == '[' {
      depth = depth + 1
      current.write_char(c)
    } else if c == ']' {
      depth = depth - 1
      current.write_char(c)
    } else if c == ',' && depth == 0 {
      let elem = current.to_string().trim().to_owned()
      if elem.is_empty() {
        raise ParseError::InvalidValue("empty array element", line_num)
      }
      result.push(elem)
      current = StringBuilder::new()
    } else {
      current.write_char(c)
    }
    i = i + 1
  }
  let last = current.to_string().trim().to_owned()
  if not(last.is_empty()) {
    result.push(last)
  }
  result
}

///|
/// Insert a value at a nested key path, detecting duplicates.
fn insert_nested(
  root : Map[String, Json],
  path : Array[String],
  value : Json,
  line_num : Int
) -> Unit raise ParseError {
  let len = path.length()
  if len == 0 {
    raise ParseError::InvalidSyntax("empty key path", line_num)
  }
  let mut current_map = root
  for i = 0; i < len; i = i + 1 {
    let key = path[i]
    if i == len - 1 {
      // Final key
      if current_map.contains(key) {
        raise ParseError::DuplicateKey(key, line_num)
      }
      current_map.set(key, value)
    } else {
      // Intermediate key - get or create nested table
      match current_map.get(key) {
        Some(Json::Object(inner_map)) => {
          current_map = inner_map
        }
        None => {
          let new_map : Map[String, Json] = Map::new()
          current_map.set(key, Json::Object(new_map))
          current_map = new_map
        }
        Some(_) => {
          raise ParseError::DuplicateKey(key, line_num)
        }
      }
    }
  }
}

///|
/// Sort a map's keys and return a new map with keys in sorted order.
fn sort_map(map : Map[String, Json]) -> Map[String, Json] {
  let keys : Array[String] = []
  for key in map.keys() {
    keys.push(key)
  }
  keys.sort()
  let result : Map[String, Json] = Map::new()
  for key in keys {
    let value = map[key]
    let sorted_value = match value {
      Json::Object(inner) => Json::Object(sort_map(inner))
      Json::Array(arr) => {
        let new_arr : Array[Json] = []
        for v in arr {
          new_arr.push(match v {
            Json::Object(inner) => Json::Object(sort_map(inner))
            _ => v
          })
        }
        Json::Array(new_arr)
      }
      _ => value
    }
    result.set(key, sorted_value)
  }
  result
}
